<script setup>
import {ref,onMounted} from 'vue'
import {Heart,ArrowLeft} from 'lucide-vue-next'
import {api,money} from '../api'
const records=ref([]),page=ref(1),total=ref(0),loading=ref(true),busy=ref(null),error=ref('')
async function load(){loading.value=true;error.value='';try{const d=await api('/favorites',{query:{page:page.value,pageSize:12}});records.value=d.records;total.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}}
async function remove(id){busy.value=id;error.value='';try{await api('/favorites/'+id,{method:'DELETE'});if(records.value.length===1&&page.value>1)page.value--;await load()}catch(e){error.value=e.message}finally{busy.value=null}}
onMounted(load)
</script>
<template><section class="wrap member-list-page"><RouterLink to="/me" class="back-link"><ArrowLeft :size="16"/>我的</RouterLink><header class="member-page-heading"><h1>我的收藏</h1><p class="muted">留住想租的器材，下次更容易找到。</p></header><p v-if="error" role="alert" class="alert error">{{error}}<button class="text-button" @click="load">重试</button></p><div v-if="loading" class="state">正在读取收藏…</div><div v-else-if="!records.length&&!error" class="state panel"><Heart :size="35"/><h3>还没有收藏器材</h3><p>在器材详情页点击收藏，便会显示在这里。</p><RouterLink class="button small" to="/">去看看推荐</RouterLink></div><div v-else class="favorite-grid"><article v-for="item in records" :key="item.id" class="favorite-card"><RouterLink v-if="item.available" :to="'/equipment/'+item.equipmentId"><img :src="item.image||'/illustrations/camera.svg'" :alt="item.equipmentName" @error="$event.target.src='/illustrations/camera.svg'"><h2>{{item.equipmentName}}</h2></RouterLink><div v-else><img :src="item.image||'/illustrations/camera.svg'" :alt="item.equipmentName"><h2>{{item.equipmentName}}</h2><p class="hint">器材已停用，暂不可预约。</p></div><div class="favorite-card-bottom"><span>¥{{money(item.dailyRate)}} / 天</span><button class="text-button" :disabled="busy===item.equipmentId" @click="remove(item.equipmentId)">{{busy===item.equipmentId?'处理中…':'取消收藏'}}</button></div></article></div><div v-if="total>12" class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/12)}}</span><button :disabled="page*12>=total||loading" @click="page++;load()">下一页</button></div></section></template>
